#include <stdexcept>

// A constexpr function that can run at compile or run time
constexpr int power(int base, int exp) noexcept {
    int res = 1;
    for (int i = 0; i < exp; ++i) res *= base;
    return res;
}

void use_at_runtime(int base) {
    // Runtime context: compiler generates normal function call
    int runtime_result = power(base, 3);
}

// Compile-time context: compiler evaluates the function
constexpr int compile_time_val = power(3, 4); // Evaluated to 81 by compiler
std::array<int, compile_time_val> data; // OK, size is 81
